    "_avisCard": {
        "fileType": "json",
        "wrapperName": "01-ajax_tutorial_manifest.html",
        "sourcePayload": "https://github.com"
    },
    "modules": [
        {
            "step": "01",
            "title": "The Network Handshake Concept",
            "description": "AJAX allows web browsers to transmit and retrieve raw data structural files securely to and from an active background engine server without forcing a full client viewport refresh window break.",
            "execution_method": "Asynchronous Network Thread Operations"
        },
        {
            "step": "02",
            "title": "The Native API Evolution",
            "methods": {
                "modern_standard": "Fetch API (Promise-driven architecture pattern tracking pipeline arrays cleanly)",
                "legacy_standard": "XMLHttpRequest (Event-driven handler state machine layer tracking status integer shifts)"
            }
        },
        {
            "step": "03",
            "title": "Handling Stream Fault Realignment",
            "description": "Always check for network transactional status bounds (HTTP 200-299) before feeding data streams directly into active client parsing logic trees to avoid full app rendering crashes."
        }
    ]
}

